<script setup lang="ts">
import {reactive,ref,watch} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {requestClient} from '#/api/request';
const props=defineProps<{programId:string}>();
const rows=ref<any[]>([]),loading=ref(false),saving=ref(false),error=ref(''),editing=ref('');
const form=reactive({title:'',chapter:'第一章',position:1,content:'',projectId:'',published:false});
function reset(){editing.value='';Object.assign(form,{title:'',chapter:'第一章',position:Math.max(0,...rows.value.map(r=>Number(r.position)))+1,content:'',projectId:'',published:false});}
async function load(){loading.value=true;error.value='';try{rows.value=await requestClient.get(`/growth/programs/${props.programId}/lessons`);}catch(e:any){error.value=e.message||'加载失败';}finally{loading.value=false;}}
function edit(row:any){editing.value=row.id;Object.assign(form,{title:row.title,chapter:row.chapter,position:row.position,content:row.content,projectId:row.project_id||'',published:Number(row.published)===1});}
async function save(){if(saving.value)return;if(!form.title.trim()||!form.content.trim()||!form.chapter.trim()){ElMessage.warning('请填写章节、标题和正文');return;}if(form.projectId&&!/^\d+$/.test(form.projectId)){ElMessage.warning('项目编号应为数字');return;}saving.value=true;try{const url=`/growth/programs/${props.programId}/lessons`;const body={...form,projectId:form.projectId||null};if(editing.value)await requestClient.put(url+'/'+editing.value,body);else await requestClient.post(url,body);await load();reset();ElMessage.success('课节已保存');}catch{/* request handler displays error */}finally{saving.value=false;}}
async function remove(row:any){try{await ElMessageBox.confirm('删除后该课节不再展示，相关进度不再计入。','删除课节');await requestClient.delete(`/growth/programs/${props.programId}/lessons/${row.id}`);await load();reset();}catch{/* cancellation or shared error handler */}}
watch(()=>props.programId,async()=>{await load();reset();},{immediate:true});
</script>
<template><div class="flex flex-col gap-4"><el-alert title="只有已报名学生可查看已发布课节。关联项目必须已上架，视频沿用项目的授权播放。" type="info" :closable="false"/><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table v-loading="loading" :data="rows" empty-text="尚未添加课节"><el-table-column prop="position" label="顺序" width="70"/><el-table-column prop="chapter" label="章节"/><el-table-column prop="title" label="标题"/><el-table-column label="状态" width="80"><template #default="{row}">{{Number(row.published)===1?'已发布':'草稿'}}</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button link type="primary" :disabled="saving" @click="edit(row)">编辑</el-button><el-button link type="danger" :disabled="saving" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
<el-form label-position="top"><div class="grid grid-cols-2 gap-4"><el-form-item label="章节"><el-input v-model="form.chapter" maxlength="100"/></el-form-item><el-form-item label="课节顺序"><el-input-number v-model="form.position" :min="1" :max="999"/></el-form-item></div><el-form-item label="课节标题"><el-input v-model="form.title" maxlength="100"/></el-form-item><el-form-item label="图文学习说明"><el-input v-model="form.content" type="textarea" :rows="6" maxlength="10000" show-word-limit/></el-form-item><el-form-item label="关联已上架手作项目编号（可选）"><el-input v-model="form.projectId" placeholder="关联项目的步骤与教学视频"/></el-form-item><el-switch v-model="form.published" active-text="向报名学生发布"/><div class="mt-4 flex gap-3"><el-button type="primary" :loading="saving" @click="save">{{editing?'保存修改':'添加课节'}}</el-button><el-button :disabled="saving" @click="reset">新建课节</el-button></div></el-form><p class="business-note">本系统不能替代专业心理咨询</p></div></template>
